package kr.releasepilot.controlplane.release;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="policy_snapshots")public class PolicySnapshot{@Id private UUID id;@Column(name="release_id",nullable=false,unique=true)private UUID releaseId;@Column(name="source_policy_version_id",nullable=false)private UUID sourcePolicyVersionId;@org.hibernate.annotations.JdbcTypeCode(org.hibernate.type.SqlTypes.JSON) @Column(nullable=false,columnDefinition="json")private String definition;@Column(nullable=false,length=64)private String checksum;@Column(name="created_at",nullable=false)private Instant createdAt;protected PolicySnapshot(){}public static PolicySnapshot create(UUID release,UUID source,String definition,String checksum,Instant now){var s=new PolicySnapshot();s.id=UUID.randomUUID();s.releaseId=release;s.sourcePolicyVersionId=source;s.definition=definition;s.checksum=checksum;s.createdAt=now;return s;}public UUID getSourcePolicyVersionId(){return sourcePolicyVersionId;}public String getChecksum(){return checksum;}public String getDefinition(){return definition;}}
